    PERFORM setval(
        pg_get_serial_sequence('"GameShop"', 'ShopId'),
        GREATEST(
            (SELECT MAX("ShopId") FROM "GameShop") + 1,
            nextval(pg_get_serial_sequence('"GameShop"', 'ShopId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Role"', 'RoleId'),
        GREATEST(
            (SELECT MAX("RoleId") FROM "Role") + 1,
            nextval(pg_get_serial_sequence('"Role"', 'RoleId'))),
        false);
    END IF;
END $EF$;

