        "TargetDiscount" smallint,
        "IsActive" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "TriggeredAt" timestamp with time zone,
        "LastNotifiedAt" timestamp with time zone,
        CONSTRAINT "PK_Alert" PRIMARY KEY ("AlertId"),
        CONSTRAINT chk_alert_condition CHECK ("TargetPrice" IS NOT NULL OR "TargetDiscount" IS NOT NULL),
        CONSTRAINT chk_alert_discount CHECK ("TargetDiscount" IS NULL OR ("TargetDiscount" BETWEEN 1 AND 100)),
        CONSTRAINT chk_alert_price CHECK ("TargetPrice" IS NULL OR "TargetPrice" > 0),
        CONSTRAINT "FK_Alert_Game_GameId" FOREIGN KEY ("GameId") REFERENCES "Game" ("GameId") ON DELETE CASCADE,
        CONSTRAINT "FK_Alert_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("UserId") ON DELETE CASCADE
    );
    END IF;
END $EF$;

